// Headless Ghidra script: decompile functions whose name matches a regex
import ghidra.app.decompiler.DecompInterface;
import ghidra.app.decompiler.DecompileResults;
import ghidra.app.script.GhidraScript;
import ghidra.program.model.listing.Function;
import ghidra.program.model.listing.FunctionIterator;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;

public class DecompileSome extends GhidraScript {

    @Override
    public void run() throws Exception {
        if (currentProgram == null) {
            println("DecompileSome: no program loaded");
            return;
        }

        String[] args = getScriptArgs();
        String pattern = (args.length > 0) ? args[0] : ".*";
        String outputPath = (args.length > 1) ? args[1] : "/tmp/decomp_some.c";

        DecompInterface decompiler = new DecompInterface();
        decompiler.openProgram(currentProgram);

        StringBuilder out = new StringBuilder();
        out.append("// program: ").append(currentProgram.getName()).append('\n');

        FunctionIterator functions = currentProgram.getListing().getFunctions(true);
        int ok = 0;
        int total = 0;
        while (functions.hasNext() && !monitor.isCancelled()) {
            Function function = functions.next();
            String name = function.getName();
            if (!name.matches(pattern)) {
                continue;
            }
            total++;
            DecompileResults result = decompiler.decompileFunction(function, 120, monitor);
            if (result != null && result.decompileCompleted() && result.getDecompiledFunction() != null) {
                out.append("\n//==== ").append(name).append(" @ ").append(function.getEntryPoint()).append("\n");
                out.append(result.getDecompiledFunction().getC());
                ok++;
            } else {
                out.append("\n// failed to decompile: ").append(name).append('\n');
            }
        }
        decompiler.dispose();

        Files.write(Paths.get(outputPath), out.toString().getBytes(StandardCharsets.UTF_8));
        println("DecompileSome: wrote " + ok + "/" + total + " functions to " + outputPath);
    }
}

